# Regenerates src/lib/pricedata.js from raw files in /workspace/research/data/global/prices/
#   eurostat_204c.json  — Eurostat nrg_pc_204_c (fetched 12 Oct 2026)
#   wb_PA.NUS.PRVT.PP.json, wb_PA.NUS.FCRF.json — World Bank WDI API, 2024 (fetched 12 Oct 2026)
# The extraction steps are recorded inline in the session; outputs: bill_components_2025.json, ppp_factor_2024.json
import json
R='/workspace/research/data/global/prices/'
b=json.load(open(R+'bill_components_2025.json')); rows=[r for r in b['rows'] if r[2][0] is not None]; rows.sort(key=lambda r:-sum(r[1]))
p=json.load(open(R+'ppp_factor_2024.json'))['factor']
open('src/lib/pricedata.js','w').write('// Generated by scripts/make_price_data.py\n// BILL: Eurostat nrg_pc_204_c, 2025, households 2,500–4,999 kWh/yr; [name, [energy&supply, network, taxes&levies] euro ¢/kWh, same in PPS ¢/kWh]\n// PPP: World Bank WDI 2024, PA.NUS.FCRF / PA.NUS.PRVT.PP\nexport const BILL = '+json.dumps(rows,ensure_ascii=False)+';\nexport const PPP = '+json.dumps(p,ensure_ascii=False)+';\n')
